def move_photos_into_galleries(apps, schema_editor):
    # The gallery row takes over the file name, so the file and its
    # thumbnails stay where they are.
    for parent_name, photo_name in GALLERIES.items():
        Parent = apps.get_model("cookbook", parent_name)
        Photo = apps.get_model("cookbook", photo_name)
        Photo.objects.bulk_create(
            Photo(parent=parent, order=0, photo=parent.photo.name)
            for parent in Parent.objects.exclude(photo="")
        )


